// examples/wander-online/shared/daily-goal.ts — deterministic realm-wide
// daily goals and their bounded JSON projection.
//
// A day hash selects among content generated by the realm's real world seed;
// it never becomes a replacement world seed. The same realm, seed and UTC
// day therefore choose the same real delivery or festival town everywhere.

import { regionName } from "../../wander/region.ts";
import { townErrand, type Errand } from "../../wander/towns.ts";
import { growHash, regionHub } from "../../wander/world.ts";

export const UTC_DAY_MS = 86_400_000;
export const DAILY_GOAL_MIN_REQUIRED = 3;
export const DAILY_GOAL_MAX_REQUIRED = 5;
export const DAILY_GOAL_CONTRIBUTION_DAYS_MAX = 32;
/** Last day representable as a four-digit ISO date (9999-12-31). */
export const DAILY_GOAL_MAX_UTC_DAY = 2_932_896;

const I32_MIN = -0x8000_0000;
const I32_MAX = 0x7fff_ffff;
const SEARCH_WIDTH = 65;
const SEARCH_COUNT = SEARCH_WIDTH * SEARCH_WIDTH;

export type DailyGoalKind = "delivery" | "landmark";
export type DailyGoalLanguage = "en" | "zh";

/** Immutable content selected for one realm day. */
export interface DailyGoal {
  realm: string;
  /** UTC days since 1970-01-01. */
  day: number;
  /** Canonical display date for `day`. */
  date: string;
  kind: DailyGoalKind;
  goalId: string;
  /** Offering town for delivery goals; null for landmark goals. */
  offerRx: number | null;
  offerRy: number | null;
  /** Delivery destination or landmark-festival town. */
  targetRx: number;
  targetRy: number;
  targetName: string;
  required: number;
  /** Exclusive UTC millisecond deadline: midnight after `day`. */
  endsAt: number;
}

/** Authenticated caller's view of the realm-wide daily progress. */
export interface DailyGoalSnapshot extends DailyGoal {
  progress: number;
  completed: boolean;
  contributed: boolean;
  /** Bounded exact history of UTC days on which this caller contributed. */
  contributionDays: number[];
  revision: number;
}

/** Authoritative gameplay fact offered to the pure goal matcher. Landmark
 * coordinates identify the newly discovered landmark, not the festival town. */
export type DailyContribution =
  | {
    realm: string;
    day: number;
    kind: "delivery";
    offerRx: number;
    offerRy: number;
    targetRx: number;
    targetRy: number;
  }
  | {
    realm: string;
    day: number;
    kind: "landmark";
    landmarkRx: number;
    landmarkRy: number;
  };

function realmId(value: unknown): value is string {
  return typeof value === "string" && /^[A-Za-z0-9][A-Za-z0-9_-]{0,31}$/.test(value);
}

function integer(value: unknown, min: number, max: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= min && value <= max;
}

function int32(value: unknown): value is number {
  return integer(value, I32_MIN, I32_MAX);
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function displayText(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= 80
    && !/[\u0000-\u001f\u007f]/.test(value);
}

function goalId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= 160
    && /^[A-Za-z0-9_-]+$/.test(value);
}

function checkedDay(day: number): number {
  if (!integer(day, 0, DAILY_GOAL_MAX_UTC_DAY)) {
    throw new RangeError(`daily goal day must be an integer in 0..${DAILY_GOAL_MAX_UTC_DAY}`);
  }
  return day;
}

/** Convert an explicit epoch timestamp to its UTC day without reading a clock. */
export function utcDayFromMs(nowMs: number): number {
  const max = (DAILY_GOAL_MAX_UTC_DAY + 1) * UTC_DAY_MS - 1;
  if (!integer(nowMs, 0, max)) throw new RangeError("daily goal time is outside the supported UTC date range");
  return Math.floor(nowMs / UTC_DAY_MS);
}

/** Canonical YYYY-MM-DD for a UTC day, implemented arithmetically so the
 * shared generator has no ambient Date dependency. */
export function utcDateForDay(input: number): string {
  const day = checkedDay(input);
  // Howard Hinnant's civil_from_days, with day 0 = 1970-01-01.
  const z = day + 719_468;
  const era = Math.floor(z / 146_097);
  const doe = z - era * 146_097;
  const yoe = Math.floor((doe - Math.floor(doe / 1_460) + Math.floor(doe / 36_524) - Math.floor(doe / 146_096)) / 365);
  let year = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const date = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const month = mp + (mp < 10 ? 3 : -9);
  if (month <= 2) year++;
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(date).padStart(2, "0")}`;
}

/** Stable ASCII realm hash. Realm ids are deliberately limited to this
 * character set by the shared social contract. */
function hashRealm(realm: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < realm.length; i++) {
    hash ^= realm.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function searchCoordinate(seed: number, realmHash: number, day: number, index: number): { rx: number; ry: number } {
  const centreX = (growHash(seed, day, realmHash, 0xd411) % 2_049) - 1_024;
  const centreY = (growHash(seed, realmHash, day, 0xd412) % 2_049) - 1_024;
  const start = growHash(seed, day ^ realmHash, realmHash, 0xd413) % SEARCH_COUNT;
  const cell = (start + index) % SEARCH_COUNT;
  return {
    rx: centreX + (cell % SEARCH_WIDTH) - (SEARCH_WIDTH >> 1),
    ry: centreY + Math.floor(cell / SEARCH_WIDTH) - (SEARCH_WIDTH >> 1),
  };
}

/** Find a delivery that the unmodified town generator actually offers. The
 * null-landmark pass cheaply filters towns with no road delivery; the second
 * call verifies that real landmark competition did not make it a visit. */
function selectDelivery(seed: number, realmHash: number, day: number): Errand {
  for (let i = 0; i < SEARCH_COUNT; i++) {
    const { rx, ry } = searchCoordinate(seed, realmHash, day, i);
    if (!regionHub(seed, rx, ry).town) continue;
    const possible = townErrand(seed, rx, ry, () => null);
    if (possible?.kind !== "deliver") continue;
    const actual = townErrand(seed, rx, ry);
    if (actual?.kind === "deliver") return actual;
  }
  throw new RangeError("daily goal search found no real delivery offer");
}

function selectFestivalTown(seed: number, realmHash: number, day: number): { rx: number; ry: number; name: string } {
  for (let i = 0; i < SEARCH_COUNT; i++) {
    const { rx, ry } = searchCoordinate(seed, realmHash, day, i);
    if (regionHub(seed, rx, ry).town) return { rx, ry, name: regionName(seed, rx, ry) };
  }
  throw new RangeError("daily goal search found no real festival town");
}

function signedBase36(value: number | null): string {
  return value === null ? "n" : value.toString(36).replace("-", "m");
}

/** Pure daily definition keyed by the real realm seed, realm id and UTC day. */
export function generateDailyGoal(inputSeed: number, realm: string, inputDay: number): DailyGoal {
  if (!Number.isSafeInteger(inputSeed)) throw new RangeError("daily goal seed must be a safe integer");
  if (!realmId(realm)) throw new RangeError("daily goal realm id is malformed");
  const seed = inputSeed >>> 0;
  const day = checkedDay(inputDay);
  const rh = hashRealm(realm);
  const roll = growHash(seed, day, rh, 0xd414);
  const kind: DailyGoalKind = (roll & 1) === 0 ? "delivery" : "landmark";
  const required = DAILY_GOAL_MIN_REQUIRED + (growHash(seed, rh, day, 0xd415) % (DAILY_GOAL_MAX_REQUIRED - DAILY_GOAL_MIN_REQUIRED + 1));
  let offerRx: number | null = null;
  let offerRy: number | null = null;
  let targetRx: number;
  let targetRy: number;
  let targetName: string;
  if (kind === "delivery") {
    const errand = selectDelivery(seed, rh, day);
    offerRx = errand.orx;
    offerRy = errand.ory;
    targetRx = errand.trx;
    targetRy = errand.try;
    targetName = errand.targetName;
  } else {
    const town = selectFestivalTown(seed, rh, day);
    targetRx = town.rx;
    targetRy = town.ry;
    targetName = town.name;
  }
  const fingerprint = growHash(seed, targetRx ^ rh, targetRy ^ day, 0xd416).toString(36);
  const kindCode = kind === "delivery" ? "d" : "l";
  const id = `dg1_${realm}_${day.toString(36)}_${kindCode}_${signedBase36(offerRx)}_${signedBase36(offerRy)}_${signedBase36(targetRx)}_${signedBase36(targetRy)}_${fingerprint}`;
  return {
    realm,
    day,
    date: utcDateForDay(day),
    kind,
    goalId: id,
    offerRx,
    offerRy,
    targetRx,
    targetRy,
    targetName,
    required,
    endsAt: (day + 1) * UTC_DAY_MS,
  };
}

/** Whether one authoritative gameplay fact advances this exact daily goal. */
export function matchesDailyContribution(goal: DailyGoal, contribution: DailyContribution): boolean {
  if (contribution.realm !== goal.realm || contribution.day !== goal.day || contribution.kind !== goal.kind) return false;
  if (goal.kind === "delivery" && contribution.kind === "delivery") {
    return contribution.offerRx === goal.offerRx && contribution.offerRy === goal.offerRy
      && contribution.targetRx === goal.targetRx && contribution.targetRy === goal.targetRy;
  }
  return contribution.kind === "landmark"
    && int32(contribution.landmarkRx) && int32(contribution.landmarkRy);
}

/** Parse the bounded authenticated JSON projection. Derived calendar and
 * completion fields must agree, so stale or future-shaped data fails closed. */
export function parseDailyGoalSnapshot(value: unknown): DailyGoalSnapshot | null {
  if (!record(value) || !realmId(value.realm)
    || !integer(value.day, 0, DAILY_GOAL_MAX_UTC_DAY)
    || typeof value.date !== "string" || value.date !== utcDateForDay(value.day)
    || (value.kind !== "delivery" && value.kind !== "landmark")
    || !goalId(value.goalId)
    || !int32(value.targetRx) || !int32(value.targetRy)
    || !displayText(value.targetName)
    || !integer(value.progress, 0, DAILY_GOAL_MAX_REQUIRED)
    || !integer(value.required, DAILY_GOAL_MIN_REQUIRED, DAILY_GOAL_MAX_REQUIRED)
    || value.progress > value.required
    || typeof value.completed !== "boolean" || value.completed !== (value.progress === value.required)
    || !integer(value.endsAt, 1, Number.MAX_SAFE_INTEGER) || value.endsAt !== (value.day + 1) * UTC_DAY_MS
    || typeof value.contributed !== "boolean"
    || !integer(value.revision, 0, 0xffff_ffff)
    || !Array.isArray(value.contributionDays)
    || value.contributionDays.length > DAILY_GOAL_CONTRIBUTION_DAYS_MAX) return null;

  const offerNull = value.offerRx === null && value.offerRy === null;
  let offerRx: number | null = null;
  let offerRy: number | null = null;
  if (int32(value.offerRx) && int32(value.offerRy)) {
    offerRx = value.offerRx;
    offerRy = value.offerRy;
  }
  const offerPair = offerRx !== null && offerRy !== null;
  if ((!offerNull && !offerPair)
    || (value.kind === "delivery" && !offerPair)
    || (value.kind === "landmark" && !offerNull)) return null;

  const contributionDays: number[] = [];
  const seen = new Set<number>();
  for (const entry of value.contributionDays) {
    if (!integer(entry, 0, value.day) || seen.has(entry)) return null;
    seen.add(entry);
    contributionDays.push(entry);
  }
  if (value.contributed !== seen.has(value.day)) return null;

  return {
    realm: value.realm,
    day: value.day,
    date: value.date,
    kind: value.kind,
    goalId: value.goalId,
    offerRx,
    offerRy,
    targetRx: value.targetRx,
    targetRy: value.targetRy,
    targetName: value.targetName,
    progress: value.progress,
    required: value.required,
    completed: value.completed,
    endsAt: value.endsAt,
    contributed: value.contributed,
    contributionDays,
    revision: value.revision,
  };
}

function han(...points: number[]): string {
  return String.fromCodePoint(...points);
}

const DAILY_ZH = {
  daily: han(0x6bcf, 0x65e5),
  delivery: han(0x9001, 0x8fbe),
  landmarkFestival: han(0x5730, 0x6807, 0x5e86, 0x5178),
} as const;

/** Compact copy for the app's one-line, 12 px bilingual surfaces. */
export function formatDailyGoal(goal: DailyGoalSnapshot, language: DailyGoalLanguage = "en"): string {
  const progress = `${goal.progress}/${goal.required}`;
  if (language === "zh") {
    const task = goal.kind === "delivery" ? DAILY_ZH.delivery : DAILY_ZH.landmarkFestival;
    return `${DAILY_ZH.daily} ${task} · ${goal.targetName} · ${progress}`;
  }
  const task = goal.kind === "delivery" ? "DELIVERY" : "LANDMARK FESTIVAL";
  return `DAILY ${task} · ${goal.targetName} · ${progress}`;
}
